css:
.sc{justify-content:flex-start;padding-top:190px;gap:30px}
.hk{font-weight:900;font-size:150px;line-height:1;text-align:center;letter-spacing:-3px}
.hk2{font-weight:900;font-size:92px;line-height:1.1;text-align:center}
.y{color:#ffd23f}.o{color:#ff5a1f}
.badge{display:flex;align-items:center;gap:28px}
.badge i{font-style:normal;width:150px;height:150px;border-radius:40px;background:#ff5a1f;color:#fff;font-weight:900;font-size:110px;display:flex;align-items:center;justify-content:center}
.badge b{font-weight:900;font-size:104px;direction:ltr}
.ben{font-weight:900;font-size:64px;line-height:1.2;text-align:center;max-width:960px}
.free{display:inline-block;background:#2ee59d;color:#063;font-weight:900;font-size:44px;padding:8px 26px;border-radius:999px}
.win{width:1000px;border-radius:30px;overflow:hidden;background:#fff;box-shadow:0 40px 120px rgba(0,0,0,.55)}
.bar{height:62px;background:#1d1d27;display:flex;align-items:center;gap:12px;padding:0 24px;direction:ltr}
.bar s{width:18px;height:18px;border-radius:50%;background:#ff5f57;display:block}.bar s:nth-child(2){background:#febc2e}.bar s:nth-child(3){background:#28c840}
.bar u{text-decoration:none;flex:1;margin-left:16px;background:#2c2c38;color:#cfcfe0;font-weight:600;font-size:28px;border-radius:12px;padding:6px 18px}
.vp{height:1080px;overflow:hidden;position:relative}
.vp img{position:absolute;left:0;top:0;width:100%;height:100%;object-fit:cover;object-position:var(--op,50% 50%);animation:kb var(--kd,4s) ease-in-out;animation-delay:var(--t)}
@keyframes kb{from{transform:scale(1)}to{transform:scale(var(--ks,1.35))}}
.fan{position:relative;width:1000px;height:640px}
.fan img{position:absolute;width:640px;border-radius:22px;box-shadow:0 30px 80px rgba(0,0,0,.6);border:6px solid #fff}
.cta{font-weight:900;font-size:120px;color:#111;text-align:center;line-height:1}
.kw{display:inline-block;background:#111;color:#ffd23f;font-weight:900;font-size:190px;padding:10px 70px;border-radius:50px;transform:rotate(-3deg)}
.h{font-weight:600;font-size:40px;opacity:.8;direction:ltr}

.sc{justify-content:center;padding-top:0;padding-bottom:120px;gap:44px}
.badge i{width:170px;height:170px;font-size:124px}.ben{font-size:76px;max-width:1000px}
.chat{width:1020px;border-radius:30px;overflow:hidden;background:#15151d;box-shadow:0 40px 120px rgba(0,0,0,.55);border:2px solid #2a2a36}
.chat .bar u{direction:ltr}
.msgs{display:flex;flex-direction:column;gap:34px;padding:50px 36px 56px}
.me{align-self:flex-start;background:#2f6bff;color:#fff;font-weight:600;font-size:60px;line-height:1.3;padding:24px 34px;border-radius:36px;border-bottom-right-radius:8px;max-width:820px}
.ai{align-self:flex-end;background:#fff;color:#111;font-weight:600;font-size:58px;line-height:1.35;padding:30px 40px;border-radius:36px;border-bottom-left-radius:8px;max-width:860px}
.ai b{color:#ff5a1f}
.doc{background:#fff8ec;color:#111;border-radius:30px;padding:50px 60px;width:1000px;box-shadow:0 30px 80px rgba(0,0,0,.45)}
.doc h3{margin:0 0 18px;font-size:70px;font-weight:900}.doc .row{font-size:56px;padding:18px 0}
.mark{background:#ffd23f;border-radius:10px;padding:0 10px}
.vs{display:flex;gap:30px}.vs>div{width:490px;border-radius:36px;padding:50px 30px;text-align:center;font-weight:900}
.vs .n{font-size:180px;line-height:1.1;direction:ltr}.vs .l{font-size:58px;margin-top:8px}

.kw2{background:#ffd23f;color:#111;font-weight:900;font-size:128px;padding:26px 60px;border-radius:44px;transform:rotate(-3deg);white-space:nowrap}
.h{font-size:52px}
